import{_ as o,o as t,c as a,a2 as d}from"./chunks/framework.Bum8orMG.js";const h=JSON.parse('{"title":"Architecture","description":"Hexagonal architecture, layer breakdown, design patterns and conventions.","frontmatter":{"title":"Architecture","description":"Hexagonal architecture, layer breakdown, design patterns and conventions."},"headers":[],"relativePath":"guides/architecture.md","filePath":"guides/architecture.md","lastUpdated":1790432985000}'),s={name:"guides/architecture.md"};function c(r,e,n,i,l,p){return t(),a("div",null,[...e[0]||(e[0]=[d(`<p>KatanaKit follows <strong>hexagonal architecture</strong> (ports and adapters). The goal is a pure, framework-agnostic core surrounded by adapters that talk to the outside world (browser APIs, HTTP, frameworks) and a shared kernel of contracts.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>               src/</span></span>
<span class="line"><span>               │</span></span>
<span class="line"><span>   ┌───────────▼───────────┐</span></span>
<span class="line"><span>   │        index.ts       │   main barrel — the public API surface</span></span>
<span class="line"><span>   └───────────┬───────────┘</span></span>
<span class="line"><span>               │</span></span>
<span class="line"><span>   ┌───────────▼───────────┐</span></span>
<span class="line"><span>   │        types/         │   shared kernel — contracts, domain types,</span></span>
<span class="line"><span>   │   (single source of   │   facades interfaces (I*), strategy contracts</span></span>
<span class="line"><span>   │        truth)         │</span></span>
<span class="line"><span>   └───────────┬───────────┘</span></span>
<span class="line"><span>               │  implements / consumes contracts</span></span>
<span class="line"><span>   ┌───────────▼──────────────────────────────────────┐</span></span>
<span class="line"><span>   │                   core/services/                 │  pure domain services</span></span>
<span class="line"><span>   │  logger · http · formatter · converter · error   │  (no I/O: no window,</span></span>
<span class="line"><span>   │  generator · dates · geometry · timing · utils   │   document, fetch, fs)</span></span>
<span class="line"><span>   │  reactive                                         │</span></span>
<span class="line"><span>   └───────────┬──────────────────────────────────────┘</span></span>
<span class="line"><span>               │  owned I/O lives one layer out</span></span>
<span class="line"><span>   ┌───────────▼──────────────────────────────────────┐</span></span>
<span class="line"><span>   │              infrastructure/                      │  browser/runtime adapters</span></span>
<span class="line"><span>   │  dom · storage · viewport · sensors              │  (guard or fall back in SSR)</span></span>
<span class="line"><span>   │  observer · worker · theme                        │</span></span>
<span class="line"><span>   └───────────┬──────────────────────────────────────┘</span></span>
<span class="line"><span>               │  framework-facing entry points</span></span>
<span class="line"><span>   ┌───────────▼──────────────────────────────────────┐</span></span>
<span class="line"><span>   │                  adapters/                       │  framework adapters</span></span>
<span class="line"><span>   │   astro/  (AstroService, RssService)            │</span></span>
<span class="line"><span>   │   express/ (ServerExpress reference)            │</span></span>
<span class="line"><span>   │   nuxt/    (pure Nuxt helpers)                  │</span></span>
<span class="line"><span>   │   vue/     (useRequest composable)          │</span></span>
<span class="line"><span>   └──────────────────────────────────────────────────┘</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ├── config/   siteConfig (typed SiteConfig) + SEO helpers (seo.service.ts)</span></span>
<span class="line"><span>   ├── prisma/   Prisma schema, generated contract types, db client</span></span></code></pre></div><h2 id="layer-by-layer" tabindex="-1">Layer-by-layer <a class="header-anchor" href="#layer-by-layer" aria-label="Permalink to &quot;Layer-by-layer&quot;">​</a></h2><h3 id="types-—-the-shared-kernel" tabindex="-1"><code>types/</code> — the shared kernel <a class="header-anchor" href="#types-—-the-shared-kernel" aria-label="Permalink to &quot;\`types/\` — the shared kernel&quot;">​</a></h3><p><code>src/types/index.ts</code> is the single source of truth for every contract and domain type in the library. It contains the strategy contracts (<code>StorageStrategy</code>, <code>ICryptoStrategy</code>, <code>IUuidStrategy</code>), the facade interfaces (<code>IFetchApiManager</code>, <code>IFormatterService</code>, <code>IConverterService</code>, <code>IErrorFactory</code>, <code>IReactiveService</code>, <code>IDomService</code>, <code>IThemeService</code>, <code>IAstroService</code>, <code>IRssService</code>, <code>DatesServiceTypes</code>, <code>IDataUtils</code>, <code>ISystemUtils</code>, <code>IAppUtils</code>) and every shared type (<code>LogLevel</code>, <code>Locale</code>, <code>Currency</code>, <code>HttpMethod</code>, <code>QueryParams</code>, <code>FetchResult</code>, <code>ApiError</code>, <code>RssConfig</code>, <code>ObserverConfig</code>, <code>ThemeOptions</code>, ...).</p><p>Services implement these contracts; adapters consume them. Domain rules never reach for concrete <code>window</code>/<code>fetch</code> globals directly.</p><h3 id="core-services-—-the-pure-layer" tabindex="-1"><code>core/services/</code> — the pure layer <a class="header-anchor" href="#core-services-—-the-pure-layer" aria-label="Permalink to &quot;\`core/services/\` — the pure layer&quot;">​</a></h3><p>Eleven service modules with pure logic. This layer never touches <code>window</code>, <code>document</code>, <code>fetch</code>, the filesystem or any framework, with two pragmatic exceptions that are clearly documented in code: <code>http.service.ts</code> wraps the global <code>fetch</code> (available in Node 18+/Bun/browsers) and <code>reactive.service.ts</code> persists via injected storage functions from <code>infrastructure</code>.</p><table tabindex="0"><thead><tr><th>File</th><th>Exports (public facade)</th></tr></thead><tbody><tr><td><code>logger.service.ts</code></td><td><code>useLogger</code>, <code>useLoggerTable</code>, <code>useLoggerClear</code></td></tr><tr><td><code>http.service.ts</code></td><td><code>FetchApiManager</code></td></tr><tr><td><code>formatter.service.ts</code></td><td><code>FormatterService</code>, <code>ConverterService</code></td></tr><tr><td><code>error.service.ts</code></td><td><code>ErrorFactoryService</code>, <code>AppError</code></td></tr><tr><td><code>generator.service.ts</code></td><td><code>GeneratorService</code>, <code>LazyNodeCryptoStrategy</code>, <code>NativeUuidStrategy</code></td></tr><tr><td><code>faker.service.ts</code></td><td><code>useFakeUuid</code>, <code>useFakeEmail</code>, <code>useFakeFullName</code>, <code>useFakeText</code>, <code>useFakeNumber</code>, <code>useFakeDate</code>, <code>useFakeVehicle</code>, <code>useFakeList</code>, <code>useFakeSeed</code>, <code>useFakeSetDefaultRefDate</code> (optional <code>@faker-js/faker</code> peer, lazy-loaded)</td></tr><tr><td><code>dates.service.ts</code></td><td><code>DatesService</code> (Temporal polyfill adapter)</td></tr><tr><td><code>geometry.service.ts</code></td><td><code>GeometryUtils</code> (<code>area</code>/<code>perimeter</code>/<code>volume</code>)</td></tr><tr><td><code>timing.service.ts</code></td><td><code>TimingService</code></td></tr><tr><td><code>utils.service.ts</code></td><td><code>DataUtils</code>, <code>SystemUtils</code>, <code>AppUtils</code></td></tr><tr><td><code>reactive.service.ts</code></td><td><code>ReactiveService</code> (signals kernel)</td></tr></tbody></table><p>Every service is a Singleton facade (<code>getInstance()</code>), exposes arrow-function methods and re-exports them <strong>destructured</strong> at the bottom of the module (<code>export const { useLogger, ... } = LoggerService.getInstance();</code>), which keeps <code>this</code> bound and lets bundlers tree-shake unused methods.</p><h3 id="infrastructure-—-the-adapter-layer" tabindex="-1"><code>infrastructure/</code> — the adapter layer <a class="header-anchor" href="#infrastructure-—-the-adapter-layer" aria-label="Permalink to &quot;\`infrastructure/\` — the adapter layer&quot;">​</a></h3><p>Adapters that own browser/runtime I/O. Each is SSR-safe: it guards or falls back gracefully when <code>window</code>/<code>document</code>/<code>navigator</code> is absent.</p><ul><li><code>dom/</code> — <code>DomService</code> (query, classes, attributes, events, HTML/text setting) plus the <code>DOM_SERVICE</code> singleton instance.</li><li><code>storage/</code> — <code>StorageService</code> over <code>localStorage</code>/<code>sessionStorage</code> with <code>LocalStorageStrategy</code>, <code>SessionStorageStrategy</code> and an in-memory <code>MemoryStorageStrategy</code> SSR fallback.</li><li><code>filesystem/</code> — Node/Bun helpers over <code>node:fs/promises</code> (<code>useReadFile</code>, <code>useWriteFile</code>, <code>useAppendFile</code>, <code>useReadJsonFile</code>, <code>useWriteJsonFile</code>, <code>useReadDir</code>, <code>useEnsureDir</code>, <code>useFileExists</code>, <code>useGetFileStats</code>, <code>useCopyFile</code>, <code>useMoveFile</code>, <code>useRemoveFile</code>, <code>useRemoveDir</code>, <code>useReadModuleFile</code>, <code>useReadModuleJson</code>) and <code>path.service.ts</code> (<code>useGetDirname</code>, <code>useResolvePath</code>, <code>useJoinPath</code>, <code>useGetRelativePath</code>, <code>useGetBasename</code>, <code>useGetFileExtension</code>, <code>useGetCwd</code>, <code>useIsNode</code>). Built-ins load through dynamic <code>import()</code>; every fallible call returns a Safe Result with the native errno <code>code</code>, and non-Node runtimes get <code>ERR_FS_UNAVAILABLE</code>. <code>useReadJsonFile</code>/<code>useReadModuleJson</code> accept an optional Zod schema.</li><li><code>viewport/</code> — <code>ViewportService</code> (dimensions, scroll, media queries, fullscreen, visibility, title).</li><li><code>sensors/</code> — <code>SensorsUtils</code> (camera/microphone, geolocation, motion, vibration, battery) exported as the <code>sensorsUtils</code> instance.</li><li><code>observer/</code> — <code>ObserverService</code> and <code>LazyLoaderService</code> wrappers around <code>IntersectionObserver</code>.</li><li><code>worker/</code> — <code>WorkerService</code> (one-shot workers and worker pools with an SSR/main-thread fallback).</li><li><code>theme/</code> — <code>ThemeService</code> (mode switching over DOM + storage + a media-query listener), exported as <code>THEME_SERVICE</code>.</li></ul><p><code>infrastructure/index.ts</code> re-exports every module and gives stable named exports to the default-exported classes (<code>StorageService</code>, <code>ViewportService</code>, <code>WorkerService</code>).</p><h3 id="adapters-—-the-framework-layer" tabindex="-1"><code>adapters/</code> — the framework layer <a class="header-anchor" href="#adapters-—-the-framework-layer" aria-label="Permalink to &quot;\`adapters/\` — the framework layer&quot;">​</a></h3><ul><li><code>astro/</code> — <code>AstroService</code> (converts collections into <code>getStaticPaths</code> payloads, Safe Result style), <code>RssService</code> (RSS 2.0 XML generation and Astro <code>GET</code> endpoints), and SEO re-exports (<code>useSeoTag</code>, <code>useHeadTags</code>, …) for Layout frontmatter. Published as <code>katanakit-js/adapters/astro</code> (Astro + RSS also available from the main barrel).</li><li><code>express/</code> — a reference Express server (<code>ServerExpress</code>), a demo <code>ProductController</code> and a <code>router</code>. Published only as the <code>katanakit-js/adapters/express</code> subpath so the main bundle never pulls in Express. Requires the <code>express</code> optional peer dependency.</li><li><code>nuxt/</code> — three <strong>pure exported functions</strong>, not singletons: <code>useUnwrap(result, context?)</code>, <code>useSafeResponse(result)</code> and <code>useEventResponse(event, result)</code>. They bridge KatanaKit <code>FetchResult</code> values to Nuxt/Nitro server routes without importing <code>h3</code>. Published only as the <code>katanakit-js/adapters/nuxt</code> subpath.</li><li><code>vue/</code> — <code>useRequest</code>, a Vue 3 composable that wraps <code>useGet</code> with the reactivity system (<code>data</code>, <code>error</code>, <code>loading</code>, <code>refetch</code>). It imports <code>vue</code> directly and is published only as the <code>katanakit-js/adapters/vue</code> subpath; <code>vue</code> is an optional peer dependency.</li></ul><h3 id="config-—-site-configuration-and-seo" tabindex="-1"><code>config/</code> — site configuration and SEO <a class="header-anchor" href="#config-—-site-configuration-and-seo" aria-label="Permalink to &quot;\`config/\` — site configuration and SEO&quot;">​</a></h3><ul><li><code>site.config.ts</code> — the <code>SiteConfig</code> interface and a default <code>siteConfig</code> instance (site URL, title, description, language, author, RSS options, SEO toggles and optional nav). Required vs optional at a glance: <code>seo</code> required · <code>rss</code> required · <code>nav?</code> optional · <code>ogImage?</code> optional. (<code>UseSeoMetaOptions</code> keeps <code>seo</code>/<code>rss</code> partial because the <code>defaults</code> fill the gaps; a full <code>SiteConfig</code> must carry them.)</li><li><code>seo.service.ts</code> — pure Nuxt-inspired <code>useSeoMeta(input, config?)</code> flat object API (<code>SeoMetaInput</code> / <code>SeoMetaFlat</code>: OG, Twitter, article, robots, canonical, …), plus <code>useApplySeoTag</code> (Vanilla), legacy <code>useSeoTag</code>, and helpers <code>useGenerateMetaTags</code>, <code>useTitle</code>, <code>useRssHeadLink</code>, <code>useHeadTags</code>. Prefer Nuxt&#39;s own head APIs inside Nuxt. <code>SiteConfig</code> inputs are validated fail-fast (<code>assertSiteConfigSeo</code> / <code>assertSiteConfigRss</code>): a missing <code>seo</code>/<code>rss</code> throws <code>[Seo] SiteConfig.seo is required (caller)</code> / <code>[Seo] SiteConfig.rss is required (caller)</code>; <code>nav</code> is copied by reference and never dereferenced, so it stays optional.</li></ul><p>Both are re-exported from the main barrel (<code>import { siteConfig, type SiteConfig, useSeoMeta } from &quot;katanakit-js&quot;</code>) and from <code>katanakit-js/adapters/astro</code>.</p><h3 id="prisma-—-database-layer-optional" tabindex="-1"><code>prisma/</code> — database layer (optional) <a class="header-anchor" href="#prisma-—-database-layer-optional" aria-label="Permalink to &quot;\`prisma/\` — database layer (optional)&quot;">​</a></h3><ul><li><code>schema.prisma</code> — the Prisma schema (<code>User</code>, <code>Post</code> models, Prisma ORM contract-first syntax).</li><li><code>schema.json</code> / <code>schema.d.ts</code> — generated contract artifacts (<strong>do not edit</strong>; regenerate with <code>prisma contract emit</code>).</li><li><code>db.ts</code> — the typed database client built with <code>@prisma/orm-postgres</code> from the contract and <code>DATABASE_URL</code> (read from <code>dotenv</code>).</li><li><code>prisma.config.ts</code> (repo root) — Prisma CLI/ORM configuration.</li></ul><p>This layer is optional: <code>@prisma/orm-postgres</code> is an optional peer dependency and the client is not exported from the main barrel.</p><h2 id="package-layout-and-esm" tabindex="-1">Package layout and ESM <a class="header-anchor" href="#package-layout-and-esm" aria-label="Permalink to &quot;Package layout and ESM&quot;">​</a></h2><ul><li><p><strong>Pure ESM.</strong> <code>package.json</code> has <code>&quot;type&quot;: &quot;module&quot;</code>, <code>&quot;module&quot;: &quot;nodenext&quot;</code> and <code>&quot;exports&quot;</code>. Source imports are relative and always carry an explicit <code>.js</code> extension (e.g. <code>import { useLogger } from &quot;./logger.service.js&quot;</code>) so the emitted <code>dist/</code> resolves identically under Node&#39;s ESM loader and bundlers.</p></li><li><p><strong>Exports map.</strong></p><table tabindex="0"><thead><tr><th>Import specifier</th><th>What it exposes</th></tr></thead><tbody><tr><td><code>katanakit-js</code></td><td>astro (Astro + RSS), config (site + SEO), core, infrastructure, types</td></tr><tr><td><code>katanakit-js/adapters/astro</code></td><td><code>AstroService</code>, <code>RssService</code>, SEO re-exports (<code>useSeoTag</code>, …)</td></tr><tr><td><code>katanakit-js/adapters/express</code></td><td>Express reference adapter</td></tr><tr><td><code>katanakit-js/adapters/nuxt</code></td><td>Nuxt helpers</td></tr><tr><td><code>katanakit-js/adapters/vue</code></td><td>Vue 3 composable</td></tr></tbody></table></li><li><p><strong><code>@/</code> alias</strong> maps to <code>src/</code> in <code>tsconfig.json</code> and <code>vitest.config.ts</code>. It is used by the test suite and the examples, not by library source files.</p></li><li><p><strong>No side effects on import.</strong> Barrel files only re-export; strategy instantiation happens lazily inside services. <code>db.ts</code> is the only module that reads the environment, and it is never part of the public barrel.</p></li></ul><h2 id="design-patterns-in-use" tabindex="-1">Design patterns in use <a class="header-anchor" href="#design-patterns-in-use" aria-label="Permalink to &quot;Design patterns in use&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pattern</th><th>Where</th></tr></thead><tbody><tr><td>Singleton</td><td>every service (<code>FetchApiManager</code>, <code>LoggerService</code>, ...)</td></tr><tr><td>Facade</td><td><code>FetchApiManager</code>, <code>DomService</code>, <code>AstroService</code>, <code>RssService</code>, <code>AppUtils</code></td></tr><tr><td>Strategy</td><td>logger output, storage backends, generator crypto/UUID, worker</td></tr><tr><td>Factory</td><td><code>ErrorFactoryService</code>; debounce/throttle/timeout factories in <code>TimingService</code></td></tr><tr><td>Observer</td><td><code>ReactiveService</code> signals, <code>ObserverService</code>, theme media query</td></tr><tr><td>Decorator</td><td><code>ConverterService</code> decorating <code>FormatterService</code></td></tr><tr><td>Adapter</td><td><code>DatesService</code> (Temporal), infrastructure layer, framework adapters</td></tr></tbody></table><h2 id="conventions" tabindex="-1">Conventions <a class="header-anchor" href="#conventions" aria-label="Permalink to &quot;Conventions&quot;">​</a></h2><ul><li><strong><code>use*</code> methods</strong> — every public method (except <code>getInstance()</code>) uses the <code>use</code> prefix, mirroring React hooks. This makes the API consistent and predictable.</li><li><strong>Destructured exports</strong> — services expose their methods as arrow-function class fields and re-export them destructured (<code>useLogger</code>, <code>useGetStorage</code>, <code>useFetch</code>, ...) for <code>this</code>-safe calls and tree-shaking. <code>ObserverService</code>, <code>LazyLoaderService</code>, <code>SensorsUtils</code> and <code>WorkerService</code> are exceptions that you call through an instance (<code>ObserverService.getInstance()</code> or the exported <code>sensorsUtils</code>).</li><li><strong>Safe Result</strong> — fallible operations return a discriminated union <code>{ data, error, ok }</code> instead of throwing: <code>FetchResult&lt;T&gt;</code>, <code>AstroServiceResult&lt;T&gt;</code>, <code>RssResult</code>.</li><li><strong>Single source of truth</strong> — all contracts and shared types live in <code>src/types/</code>.</li><li><strong>English only</strong> — comments, identifiers and messages are written in English.</li></ul><h2 id="development-tooling" tabindex="-1">Development tooling <a class="header-anchor" href="#development-tooling" aria-label="Permalink to &quot;Development tooling&quot;">​</a></h2><ul><li><code>bun run check</code> — ESLint + Prettier + typecheck + tests (gate before build/publish).</li><li><code>bun run fix</code> — same as <code>check</code> with ESLint + Prettier auto-fix.</li><li><code>bun run build</code> — <code>check</code> then <code>tsc</code> → <code>dist/</code>.</li><li><code>bun run release -- &lt;patch|minor|major&gt;</code> — <code>build</code> → version bump → publish.</li><li><code>bun run docs -- &lt;dev|build|serve&gt;</code> — docs site (<code>build</code> runs <code>check</code> + clear first).</li><li><code>bun run dev</code> — the bundled Express example server.</li></ul><p>See <a href="https://github.com/senseikatana/katanakit-js/blob/dev/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING.md</a> for the full development contract.</p>`,31)])])}const g=o(s,[["render",c]]);export{h as __pageData,g as default};
